<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class DepartmentWorkspaceController extends Controller{
 public function index(Request $r){$u=$r->user();$p=$r->attributes->get('academic_period');abort_if(!$p,404,'Учебный период не выбран');$teacherId=$u->teacher_id??null;$admin=$u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head');$departments=DB::table('academic_departments')->where('active',1)->when(!$admin,fn($q)=>$q->where('head_teacher_id',$teacherId))->orderBy('name')->get();abort_if($departments->isEmpty()&&!$admin,403);$id=$r->integer('department')?:($departments->first()->id??0);abort_unless($admin||$departments->contains('id',$id),403);$department=DB::table('academic_departments')->find($id);if(!$department)return view('departments.workspace',['departments'=>$departments,'department'=>null]);
 $groups=DB::table('study_groups as g')->leftJoin('specialties as sp','sp.id','=','g.specialty_id')->where('g.academic_department_id',$id)->where('g.active',1)->select('g.*','sp.code as specialty_code','sp.name as specialty_name')->orderBy('g.name')->get();$gids=$groups->pluck('id');
 $students=DB::table('students')->whereIn('current_group_id',$gids)->where('status','active')->count();$leave=DB::table('students')->whereIn('current_group_id',$gids)->where('status','academic_leave')->count();$teachers=DB::table('teachers')->where('academic_department_id',$id)->where('active',1)->orderBy('last_name')->get();
 $groupStats=collect();foreach($groups as $g){$sids=DB::table('students')->where(['current_group_id'=>$g->id,'status'=>'active'])->pluck('id');$avg=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where('l.academic_period_id',$p->id)->whereIn('gr.student_id',$sids)->avg(DB::raw('CAST(gr.value AS REAL)'));$missed=DB::table('attendance_records as ar')->join('lesson_occurrences as l','l.id','=','ar.lesson_occurrence_id')->where('l.academic_period_id',$p->id)->whereIn('ar.student_id',$sids)->whereIn('ar.status',['absent','sick','excused'])->count();$debtorIds=collect();foreach($sids as $sid){$legacy=DB::table('semester_results')->where(['academic_period_id'=>$p->id,'student_id'=>$sid])->whereIn('value',['2','незачет','незачёт','не зачтено'])->exists();$latest=DB::table('attestation_attempts as aa')->join('attestation_sheets as sh','sh.id','=','aa.attestation_sheet_id')->where(['sh.academic_period_id'=>$p->id,'aa.student_id'=>$sid])->whereRaw('aa.attempt_no=(select max(a2.attempt_no) from attestation_attempts a2 where a2.attestation_sheet_id=aa.attestation_sheet_id and a2.student_id=aa.student_id)')->where('aa.passed',0)->exists();if($legacy||$latest)$debtorIds->push($sid);}$notAdmitted=DB::table('attestation_admissions')->where('academic_period_id',$p->id)->whereIn('student_id',$sids)->whereNull('subject_id')->where('status','not_admitted')->count();$retakes=DB::table('attestation_attempts as aa')->join('attestation_sheets as sh','sh.id','=','aa.attestation_sheet_id')->where('sh.academic_period_id',$p->id)->whereIn('aa.student_id',$sids)->where('aa.attempt_no','>',0)->whereNull('aa.completed_at')->count();$groupStats->put($g->id,(object)['id'=>$g->id,'students_count'=>$sids->count(),'avg_grade'=>$avg,'missed'=>$missed,'debtors'=>$debtorIds->unique()->count(),'not_admitted'=>$notAdmitted,'retakes'=>$retakes]);}
 $movements=DB::table('student_movements as m')->join('students as s','s.id','=','m.student_id')->leftJoin('study_groups as fg','fg.id','=','m.from_group_id')->leftJoin('study_groups as tg','tg.id','=','m.to_group_id')->where(function($q)use($gids){$q->whereIn('m.from_group_id',$gids)->orWhereIn('m.to_group_id',$gids);})->select('m.*','s.last_name','s.first_name','fg.name as from_group','tg.name as to_group')->orderByDesc('m.effective_on')->limit(20)->get();
 $totalDebtors=$groupStats->sum('debtors');$totalNotAdmitted=$groupStats->sum('not_admitted');$totalRetakes=$groupStats->sum('retakes');$avgGrade=$groupStats->where('avg_grade','!==',null)->avg('avg_grade');return view('departments.workspace',compact('p','departments','department','groups','groupStats','students','leave','teachers','movements','totalDebtors','totalNotAdmitted','totalRetakes','avgGrade'));
 }
}